const raw = $json.request_id ? $json : (($json.body && $json.body.request_id) ? $json.body : $json);

function errorResult(code, message) {
  return [{
    json: {
      adapter_status: "error",
      component_id: "ADP-SLACK-SEND",
      component_version: "v1",
      request_id: raw.request_id || null,
      source_component: raw.source_component || null,
      provider: "slack",
      operation: "send_message",
      validation_status: "invalid",
      channel: raw.slack?.channel || null,
      message_ts: null,
      manual_review_required: true,
      error_code: code,
      error_message: message,
      next_action: "route_to_manual_review_or_error_log",
      status_log_event: "slack_send_validation_error",
      downstream_components: ["C5-E", "C6-G", "C5-W"],
      source_result: null,
      original_input: raw
    }
  }];
}

if (!raw.request_id) return errorResult("MISSING_REQUEST_ID", "request_id is required.");
if (!raw.slack || typeof raw.slack !== "object") return errorResult("MISSING_SLACK_OBJECT", "slack object is required.");

const slack = raw.slack;
const channel = String(slack.channel || "").trim();
const message = String(slack.message || "").trim();
const title = String(slack.title || "").trim();
const priority = String(slack.priority || "normal").trim().toLowerCase();
const threadTs = slack.thread_ts === undefined || slack.thread_ts === null ? "" : String(slack.thread_ts).trim();

const allowedPriorities = ["low", "normal", "high", "critical"];

if (!channel) return errorResult("MISSING_CHANNEL", "slack.channel is required.");
if (!message) return errorResult("MISSING_MESSAGE", "slack.message is required.");
if (!allowedPriorities.includes(priority)) return errorResult("INVALID_PRIORITY", "slack.priority must be low, normal, high, or critical.");

const prefixMap = {
  low: "ℹ️",
  normal: "✅",
  high: "⚠️",
  critical: "🚨"
};

const priorityLabel = priority.toUpperCase();
const titleLine = title ? `*${title}*` : "*Automation Notification*";
const text = `${prefixMap[priority]} ${titleLine}\n*Priority:* ${priorityLabel}\n*Source:* ${raw.source_component || "unknown"}\n*Request:* ${raw.request_id}\n\n${message}`;

const slackOut = {
  channel,
  text
};

if (threadTs) {
  slackOut.thread_ts = threadTs;
}

return [{
  json: {
    adapter_status: "ready",
    component_id: "ADP-SLACK-SEND",
    component_version: "v1",
    request_id: raw.request_id,
    source_component: raw.source_component || null,
    provider: "slack",
    operation: "send_message",
    validation_status: "valid",
    channel,
    slack: slackOut,
    routing_options: raw.routing_options || {},
    metadata: raw.metadata || {},
    manual_review_required: false,
    error_code: null,
    error_message: null,
    next_action: "execute_slack_send",
    status_log_event: "slack_send_request_validated",
    original_input: raw
  }
}];

const validation = $node["Normalize And Validate Slack Request"].json;
const providerResult = $json;

const hasError = Boolean(providerResult.error || providerResult.ok === false || providerResult.message?.includes?.("ERROR"));

if (hasError) {
  return [{
    json: {
      adapter_status: "error",
      component_id: "ADP-SLACK-SEND",
      component_version: "v1",
      request_id: validation.request_id || null,
      source_component: validation.source_component || null,
      provider: "slack",
      operation: "send_message",
      validation_status: validation.validation_status || "valid",
      channel: validation.channel || null,
      message_ts: null,
      manual_review_required: true,
      error_code: "SLACK_SEND_FAILED",
      error_message: providerResult.error || providerResult.message || "Slack send failed.",
      next_action: "route_to_manual_review_or_error_log",
      status_log_event: "slack_send_failed",
      downstream_components: ["C5-E", "C6-G", "C5-W"],
      source_result: providerResult,
      original_input: validation.original_input || null
    }
  }];
}

return [{
  json: {
    adapter_status: "success",
    component_id: "ADP-SLACK-SEND",
    component_version: "v1",
    request_id: validation.request_id || null,
    source_component: validation.source_component || null,
    provider: "slack",
    operation: "send_message",
    validation_status: "valid",
    channel: providerResult.channel || validation.channel || null,
    message_ts: providerResult.ts || providerResult.message?.ts || null,
    manual_review_required: false,
    error_code: null,
    error_message: null,
    next_action: validation.routing_options?.on_success || "log_status",
    status_log_event: "slack_send_success",
    downstream_components: ["C5-W"],
    source_result: providerResult,
    original_input: validation.original_input || null
  }
}];
